  _wait(v, err) { const ms = this.rttMs; return new Promise((ok, no) => setTimeout(() => (err ? no(err) : ok(v)), ms)); }
  _send(name, args) {
    this.roundTrips++;
    if (this.down) return this._wait(null, new Error('connect ECONNREFUSED 127.0.0.1:6379'));
