  }
  pipeline() {
    const self = this, q = [], p = {};
    for (const n of FakeRedis.names) p[n] = (...a) => { q.push([n, a]); return p; };
    p.exec = () => {
      self.roundTrips++;
      if (self.down) return self._wait(null, new Error('connect ECONNREFUSED 127.0.0.1:6379'));
